<template><section class="expert-card"><h2>Validador de compatibilidad</h2><p>Revisa una proforma como conjunto de piezas o como accesorios para otro equipo. Esta evaluación es independiente del diagnóstico experto.</p><tecnico-proformas ref="quotes" :disabled="busy" @select="importQuote"/><div v-if="!value.assembly" class="expert-fields"><label>Equipo de destino<input :value="value.equipment" @input="update('equipment',$event.target.value)"></label><label>Modelo de destino<input :value="value.model" @input="update('model',$event.target.value)"></label></div><label>Requisitos o dudas de compatibilidad<textarea :value="value.request" @input="update('request',$event.target.value)" rows="2" maxlength="6000" placeholder="Ej. Revisar CPU, placa, memoria, fuente y espacio del gabinete."></textarea></label><p v-if="error" class="expert-error" role="alert">{{error}}</p><p v-if="busy" role="status">Comparando las piezas y sus especificaciones…</p><tecnico-compatibilidad :products="value.quoteProducts" :results="value.compatibility" :assembly="value.assembly" :busy="busy" @assembly="update('assembly',$event)" @analyze="analyze" @investigate="$emit('investigate',$event)"/><p v-if="!value.quoteProducts.length" class="expert-note">Busca una proforma para cargar las piezas que deseas evaluar.</p><section v-if="value.analysis"><h3>Conclusión del validador</h3><p class="expert-output">{{value.analysis}}</p><details v-if="value.sources.length"><summary>Fuentes del validador</summary><ul><li v-for="source in value.sources" :key="source.url"><a :href="source.url" target="_blank" rel="noopener noreferrer">{{source.title||source.url}}</a></li></ul></details></section></section></template>
<script>
import TecnicoProformas from './TecnicoProformas.vue'
import TecnicoCompatibilidad from './TecnicoCompatibilidad.vue'
export default {components:{TecnicoProformas,TecnicoCompatibilidad},props:{value:Object,settings:Object},data(){return {busy:false,error:''}},beforeDestroy(){if(this.controller)this.controller.abort()},methods:{openQuotes(){this.$refs.quotes.open=true;this.$refs.quotes.page=1;this.$refs.quotes.search()},update(key,value){this.$emit('input',Object.assign({},this.value,{[key]:value,compatibility:[],analysis:'',sources:[]}))},importQuote(result){this.$emit('input',Object.assign({},this.value,{quoteProducts:result.products.slice(0,25).map((p,i)=>({key:String(i),name:p.Producto||'',model:p.ProductoModelo||'',specs:String(p.Descripcion||p.ProductoDesc||'').slice(0,2000)})),comparison:result.text,compatibility:[],analysis:'',sources:[]}))},async analyze(){if(this.busy)return;this.error='';if(!this.settings||!this.settings.configured){this.error='Activa OpenAI en ALI para evaluar.';return}if(!this.value.assembly&&!this.value.equipment.trim()&&!this.value.model.trim()){this.error='Indica el equipo o modelo de destino.';return}this.busy=true;this.controller=new AbortController;const timer=setTimeout(()=>this.controller.abort(),160000);try{const data=Object.assign({},this.value,{title:'Validación de compatibilidad de proforma',mode:'compatibilidad',request:this.value.request||'Evaluar la compatibilidad de las piezas indicadas. Identificar conflictos, diferencias y alternativas verificadas.'});const response=await fetch('/api/index.php/ali/tecnico',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Ali-CSRF':this.settings.csrf},body:JSON.stringify({action:'analyze',data,files:[]}),signal:this.controller.signal});const result=await response.json();if(!response.ok)throw Error(result.error||'No se pudo evaluar.');this.$emit('input',Object.assign({},this.value,{compatibility:result.compatibility||[],analysis:result.analysis||'',sources:result.sources||[]}))}catch(e){this.error=e.name==='AbortError'?'La evaluación tardó demasiado. Intenta nuevamente.':e.message}finally{clearTimeout(timer);this.busy=false}}}}
</script>
